"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["62218"],{17145(e,t,n){n.r(t),n.d(t,{metadata:()=>r,default:()=>g,frontMatter:()=>c,contentTitle:()=>u,toc:()=>d,assets:()=>h});var r=JSON.parse('{"id":"nhcx/v1/api/other/endpoints/other-swagger-resources-configuration-security","title":"Get the swagger security configuration","description":"Returns the Swagger UI security configuration for the status service; consumed by Swagger UI, not by integrations.","source":"@site/docs/nhcx/v1/api/other/endpoints/other-swagger-resources-configuration-security.mdx","sourceDirName":"nhcx/v1/api/other/endpoints","slug":"/nhcx/v1/api/other/endpoints/other-swagger-resources-configuration-security","permalink":"/docs/pr-32/docs/nhcx/v1/api/other/endpoints/other-swagger-resources-configuration-security","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Get the swagger security configuration","sidebar_label":"Get the swagger security configuration","sidebar_class_name":"api-method api-method--get","description":"Returns the Swagger UI security configuration for the status service; consumed by Swagger UI, not by integrations.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-other.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Get the swagger UI configuration","permalink":"/docs/pr-32/docs/nhcx/v1/api/other/endpoints/other-swagger-resources-configuration-ui"},"next":{"title":"Submit the status callback","permalink":"/docs/pr-32/docs/nhcx/v1/api/other/endpoints/other-v1-on-status"}}'),s=n(62540),a=n(43023),o=n(85030),i=JSON.parse('{"id":"other_swagger_resources_configuration_security","module":"Other","moduleId":"other","kind":"operation","method":"GET","path":"/swagger-resources/configuration/security","server":"https://apisbx.abdm.gov.in/hcx","servers":[{"url":"https://apisbx.abdm.gov.in/hcx","description":"Sandbox, NHCX exchange."},{"url":"https://apisprod.nha.gov.in/hcx","description":"Production."}],"summary":"Swagger security configuration","title":"Get the swagger security configuration","description":"Returns the Swagger UI security configuration for the status service; consumed by Swagger UI, not by integrations.\\n\\n### Business purpose\\n\\nSwagger UI reads this endpoint to learn how to present authorisation inputs (such as a bearer token field) when a user tries operations from the browser. It describes UI behaviour only; it does not issue tokens, and it is unrelated to the client-credentials flow at /get/session or to the JWE encryption that protects protocol payloads. The endpoint index describes it as the Swagger security configuration.\\n\\n### When to use\\n\\nUse it only in a Swagger UI session against the status service. It does not issue tokens, and integrations never call it.\\n\\n### Preconditions\\n\\n- A plain `GET` to the status service host, under `/statushcxservice`.\\n- No encryption, no `x-hcx-*` headers and no request body.\\n\\n### Postconditions\\n\\nThe service returns `200` with the UI\'s security settings. No token is issued and no callback follows.\\n\\n### Common mistakes\\n\\n- Calling the gateway address instead of the status service host.\\n- Treating this document as the contract for gateway traffic.\\n- Sending a `POST`, a request body or `x-hcx-*` headers.\\n- Mistaking it for a way to get a token.\\n\\n### Best practices\\n\\n- Use these endpoints for exploration and client generation in the sandbox, and cache the document rather than fetching it on every run.\\n- Diff the served document against the corpus (Status service: OpenAPI 3.0.1, version 1.0.0) when behaviour changes unexpectedly.\\n- Never let production traffic depend on the availability of the documentation endpoints.\\n- Keep the /v1/status protocol rules in mind when reading the spec: x-hcx-correlation_ID must carry the original request\'s correlation ID.\\n\\n### Related scenario\\n\\nA provider\'s engineer wants to try /v1/status from Swagger UI in the sandbox. The UI fetches /swagger-resources/configuration/security to decide how to show the authorisation dialog, and the engineer pastes a Bearer token obtained separately from the client-credentials call. Because the status request body must be a JWE built with the payer\'s certificate, the engineer ultimately uses the UI only to confirm the schema and runs the real status request from the integration code, which reuses the original preauth correlation ID.\\n\\n### Specification\\n\\nChapter [Environments and addresses](/docs/nhcx/v1/reference/environments-and-addresses) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[],"responses":[{"status":"200","description":"The service returns HTTP 200 with a small JSON object describing how Swagger UI should handle security inputs.","example":{"apiKeyVehicle":"header","apiKeyName":"bearer_auth","scopeSeparator":","}}],"curl":"curl --request GET \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/swagger-resources/configuration/security \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request GET \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/swagger-resources/configuration/security \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.get(\\n    \\"https://apisbx.abdm.gov.in/hcx/swagger-resources/configuration/security\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node.js","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/hcx/swagger-resources/configuration/security\\", {\\n  method: \\"GET\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n  },\\n});\\n\\nconsole.log(response.status, await response.text());"},{"id":"java","label":"Java","language":"java","code":"import java.net.URI;\\nimport java.net.http.HttpClient;\\nimport java.net.http.HttpRequest;\\nimport java.net.http.HttpResponse;\\n\\nHttpClient client = HttpClient.newHttpClient();\\nHttpRequest request = HttpRequest.newBuilder()\\n    .uri(URI.create(\\"https://apisbx.abdm.gov.in/hcx/swagger-resources/configuration/security\\"))\\n    .header(\\"Authorization\\", \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\")\\n    .header(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n    .method(\\"GET\\", HttpRequest.BodyPublishers.noBody())\\n    .build();\\n\\nHttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());\\nSystem.out.println(response.statusCode() + \\" \\" + response.body());"},{"id":"php","label":"PHP","language":"php","code":"<?php\\n\\n$ch = curl_init(\'https://apisbx.abdm.gov.in/hcx/swagger-resources/configuration/security\');\\ncurl_setopt_array($ch, [\\n    CURLOPT_CUSTOMREQUEST => \'GET\',\\n    CURLOPT_RETURNTRANSFER => true,\\n    CURLOPT_HTTPHEADER => [\\n        \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\',\\n        \'bearer_auth: Bearer <access token>\',\\n    ],\\n]);\\n\\n$response = curl_exec($ch);\\necho curl_getinfo($ch, CURLINFO_HTTP_CODE), \' \', $response, PHP_EOL;"},{"id":"go","label":"Go","language":"go","code":"package main\\n\\nimport (\\n\\t\\"fmt\\"\\n\\t\\"io\\"\\n\\t\\"net/http\\"\\n)\\n\\nfunc main() {\\n\\treq, err := http.NewRequest(\\"GET\\", \\"https://apisbx.abdm.gov.in/hcx/swagger-resources/configuration/security\\", nil)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\treq.Header.Set(\\"Authorization\\", \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\")\\n\\treq.Header.Set(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n\\n\\tresp, err := http.DefaultClient.Do(req)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\tdefer resp.Body.Close()\\n\\tout, _ := io.ReadAll(resp.Body)\\n\\tfmt.Println(resp.StatusCode, string(out))\\n}"},{"id":"csharp","label":"C#","language":"csharp","code":"using var client = new HttpClient();\\nvar request = new HttpRequestMessage(new HttpMethod(\\"GET\\"), \\"https://apisbx.abdm.gov.in/hcx/swagger-resources/configuration/security\\");\\nrequest.Headers.TryAddWithoutValidation(\\"Authorization\\", \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\");\\nrequest.Headers.TryAddWithoutValidation(\\"bearer_auth\\", \\"Bearer <access token>\\");\\n\\nvar response = await client.SendAsync(request);\\nConsole.WriteLine($\\"{(int)response.StatusCode} {await response.Content.ReadAsStringAsync()}\\");"},{"id":"ruby","label":"Ruby","language":"ruby","code":"require \'net/http\'\\n\\nuri = URI(\'https://apisbx.abdm.gov.in/hcx/swagger-resources/configuration/security\')\\nrequest = Net::HTTP::Get.new(uri)\\nrequest[\'Authorization\'] = \'Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\'\\nrequest[\'bearer_auth\'] = \'Bearer <access token>\'\\n\\nresponse = Net::HTTP.start(uri.hostname, uri.port, use_ssl: uri.scheme == \'https\') do |http|\\n  http.request(request)\\nend\\nputs response.code, response.body"}]}');let c={title:"Get the swagger security configuration",sidebar_label:"Get the swagger security configuration",sidebar_class_name:"api-method api-method--get",description:"Returns the Swagger UI security configuration for the status service; consumed by Swagger UI, not by integrations.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-other.yaml",generated:!0},u,h={},d=[];function p(e){return(0,s.jsx)(o.A,{operation:i})}function g(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(p,{...e})}):p(e)}}}]);